The subject (who asks) is not part of the request. It lives inside the authorizer instance, so a server builds one authorizer per connection or session, for example from the roles in a JWT it has already verified, and maps them to actions and resources. Roles are not a library concept: use std::sync::Arc;
use graphersal::prelude::*;
use graphersal::auth::{AccessRequest, Action, Authorizer, Denied, Resource}; /// Built per connection from the verified token's claims.
struct Session { roles: Vec<String>,
} impl Session { fn has(&self, role: &str) -> bool { self.roles.iter().any(|r| r == role) }
} impl Authorizer for Session { fn authorize(&self, request: &AccessRequest<'_>) -> Result<(), Denied> { let allowed = match (request.action, request.resource) { (_, _) if self.has("admin") => true, // Everybody reads data and the schema. (Action::Read, Resource::Data { .. } | Resource::Schema) => true, // Editors change data, except elements labelled `salary`. (Action::Create | Action::Update | Action::Delete, Resource::Data { label, .. }) => { self.has("editor") && label != Some("salary") } // Server-owned resources go through the same policy. (Action::Custom("open"), Resource::Custom { kind: "database", name }) => { name == Some("shared") || self.has("dba") } _ => false, }; if allowed { Ok(()) } else { Err(Denied::new(format!("{request} needs another role"))) } }
} let session = Arc::new(Session { roles: vec!["editor".into()] });
// The server checks its own resources at its own boundary ...
let open = AccessRequest::new( Action::Custom("open"), Resource::Custom { kind: "database", name: Some("shared") },
);
assert!(session.authorize(&open).is_ok());
// ... and hands the same authorizer to the script entry.
let graph = Arc::new(GraphSource::tinkerpop_modern());
let denied = graphersal::script::eval_value_with_limits( graph, r#"g.addV("salary").property("amount", 1).next()"#, Default::default(), &graphersal::script::ScriptLimits::default(), session,
);
assert!(denied.unwrap_err().to_string().contains("needs another role")); Resource::Custom and Action::Custom are never produced by the library: they exist so that an embedding server can put its own resources (databases, tenants, endpoints) under the same policy and call authorize itself.

