Function Returns Cypher spelling size(list), cardinality(list) the number of items (size(e) of a group variable counts its edges) size(list) head(list), last(list) the first / last item; NULL for [] compatibility function tail(list) all items but the first compatibility function trim(list, n) the list without its last n items range(start, end [, step]) the integers from start to end inclusive, by step (default 1) compatibility function keys(x) the property keys of a vertex or edge (a stored null is no key), or the keys of a map compatibility function properties(x) the properties of a vertex or edge as a map; a map itself compatibility function startNode(e), endNode(e) the stored source / target vertex of the edge compatibility function n IS [NOT] SOURCE OF e, n IS [NOT] DESTINATION OF e whether n is the edge's source / target (a predicate) nodes(p), relationships(p) the vertices / the edges of a path, in the path's order compatibility function startNode(e) is the edge's stored source, whatever direction the pattern was written in: in (a)-[e]-(b) the variable a may be either end. range() checks its size before it builds the list, so range(0, 9223372036854775807) is a limit error, never an out-of-memory ( Errors ). g.gql("MATCH (n:person {name: 'marko'}) RETURN head([1, 2, 3]) AS h, last([1, 2, 3]) AS l, tail([1, 2, 3]) AS t, trim([1, 2, 3], 1) AS tr, range(1, 5) AS r, range(10, 0, -5) AS d, head([]) AS e").to_list()
// #{"d": [10, 5, 0], "e": (), "h": 1, "l": 3, "r": [1, 2, 3, 4, 5], "t": [2, 3], "tr": [1, 2]}
g.gql("MATCH (p:person)-[:created]->(s) WITH p, s ORDER BY s.name RETURN p.name AS name, head(collect(s.name)) AS first ORDER BY name").to_list()
// #{"first": "lop", "name": "josh"}, #{"first": "lop", "name": "marko"}, #{"first": "lop", "name": "peter"}
g.gql("MATCH (n:person {name: 'marko'}) RETURN keys(n) AS k, properties(n) AS p").to_list() // #{"k": ["name", "age"], "p": #{"age": 29, "name": "marko"}}
g.v().has("name", "marko").properties().key().fold().to_list() // ["name", "age"]
g.v().has("name", "marko").value_map().by(__.unfold()).to_list() // #{"age": 29, "name": "marko"}
g.gql("MATCH (a)-[e:knows]-(b) RETURN a.name AS a, b.name AS b, startNode(e).name AS s, endNode(e).name AS t ORDER BY a, b").to_list()
// josh marko: s marko, t josh; marko josh: marko, josh; marko vadas: marko, vadas; vadas marko: marko, vadas
g.e().has_label("knows").project("s", "t").by(__.out_v().values("name")).by(__.in_v().values("name")).to_list()
// #{"s": "marko", "t": "vadas"}, #{"s": "marko", "t": "josh"}
g.gql("MATCH (a)-[e:knows]-(b) RETURN a.name AS a, b.name AS b, a IS SOURCE OF e AS src ORDER BY a, b").to_list()
// josh marko false, marko josh true, marko vadas true, vadas marko false
g.gql("MATCH p = (a {name: 'marko'})-[:knows|created]->{1,2}(b) RETURN b.name AS b, size(nodes(p)) AS n, size(relationships(p)) AS r, last(nodes(p)) = b AS same ORDER BY n, b").to_list()
// josh 2 1 true, lop 2 1 true, vadas 2 1 true, lop 3 2 true, ripple 3 2 true
g.gql("MATCH (n:person {name: 'marko'}) RETURN range(0, 9223372036854775807) AS r") // error: Resource limit 'traversal.max_materialized_bytes' exceeded A list comprehension maps or filters the items of a list ([x IN nodes(p) | x.name]); FOR walks a list as rows and collect_list() collects them again: g.gql("MATCH p = (a {name: 'marko'})-[:knows]->(b) RETURN b.name AS b, [x IN nodes(p) | x.name] AS names ORDER BY b").to_list()
// #{"b": "josh", "names": ["marko", "josh"]}, #{"b": "vadas", "names": ["marko", "vadas"]}
g.gql("MATCH p = (a {name: 'marko'})-[:knows]->(b) FOR x IN nodes(p) RETURN b.name AS b, collect_list(x.name) AS names ORDER BY b").to_list()
// #{"b": "josh", "names": ["marko", "josh"]}, #{"b": "vadas", "names": ["marko", "vadas"]}

