graph.set_schema({ "mode": "open", "vertices": { "chunk": {"schema": {"type": "object", "properties": { "text": {"type": "string"}, "emb": {"type": "array", "format": "vector", "element": "f32", "dimension": 384, "metric": "cosine"}, }}}, },
}) # The host's data: documents cut into chunks, plus the topics each document mentions.
docs = [ {"title": "Cat care", "topics": ["pets", "health"], "chunks": [ "Cats need fresh water every day.", "Most adult cats do well on two meals a day.", ]}, {"title": "Weeknight pasta", "topics": ["cooking"], "chunks": [ "Salt the pasta water generously.", ]},
] for doc in docs: graph.execute('g.add_v("doc").property("title", title).iterate()', params={"title": doc["title"]}) for topic in doc["topics"]: graph.execute( 'g.merge_v(#{"T.label": "topic", name: topic}).as("t")' '.v().has("doc", "title", title).add_e("mentions").to("t").iterate()', params={"title": doc["title"], "topic": topic}, ) embs = model.encode(doc["chunks"]) # numpy float32, shape (n, 384) for text, emb in zip(doc["chunks"], embs): graph.execute( 'g.v().has("doc", "title", title).as("d")' '.add_v("chunk").property("text", text).property("emb", emb)' '.add_e("part_of").to("d").iterate()', params={"title": doc["title"], "text": text, "emb": emb}, ) A one-dimensional float32 numpy array passed in params arrives in the script as an f32 vector (so does a graphersal.Vector(values), built from a list or a buffer); the extension reads it through memoryview and does not depend on numpy. A list in params is not supported: wrap it in graphersal.Vector(..). The search embeds the question with the same model and passes it as a parameter: question = "How often should I feed my cat?"
q = model.encode(question) hits = graph.query(""" g.v().has_label("chunk").nearest("emb", q, 3) .project("text", "score") .by("text") .by(__.similarity("emb", q)) .to_list()
